import{_ as o,o as t,c as d,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"鉴权与权限模型","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/auth.md","filePath":"advanced/auth.md","lastUpdated":1790784770000}'),c={name:"advanced/auth.md"};function a(s,e,i,n,l,p){return t(),d("div",null,[...e[0]||(e[0]=[r(`<h1 id="鉴权与权限模型" tabindex="-1">鉴权与权限模型 <a class="header-anchor" href="#鉴权与权限模型" aria-label="Permalink to &quot;鉴权与权限模型&quot;">​</a></h1><p>这一页说明 ZViewer 怎样确认一个人的身份、怎样给他分配权限，以及前端在登录态还没确定时如何取舍。</p><h2 id="token-体系" tabindex="-1">Token 体系 <a class="header-anchor" href="#token-体系" aria-label="Permalink to &quot;Token 体系&quot;">​</a></h2><p>ZViewer 用两个 JWT 做身份认证，实现在 <code>middleware/auth.ts</code>。JWT（JSON Web Token，一种把用户身份签名后放进令牌的机制）由服务器签发一次，客户端每次请求带上它，服务器验签通过就认可身份，不必查会话表。两种令牌的分工如下表。</p><table tabindex="0"><thead><tr><th>Token</th><th>默认有效期</th><th>环境变量</th><th>通道</th></tr></thead><tbody><tr><td>Access（正式用户）</td><td><strong>1 小时</strong></td><td><code>JWT_ACCESS_EXPIRES_IN</code></td><td>httpOnly Cookie + Bearer 头 + query <code>token</code></td></tr><tr><td>Refresh（正式用户）</td><td><strong>30 天</strong></td><td><code>JWT_REFRESH_EXPIRES_IN</code></td><td>httpOnly Cookie（<code>POST /refresh</code> 也接受 body）</td></tr><tr><td>Access（guest）</td><td>1 小时</td><td>—</td><td>同上</td></tr><tr><td>Refresh（guest）</td><td>7 天</td><td>—</td><td>同上</td></tr></tbody></table><ul><li><p><strong>payload</strong>（令牌里携带的数据）为 <code>{ userId, role, username?, iat }</code>。</p></li><li><p><strong>同一套令牌要支持三种传递方式，是因为三种场景各有各的限制。</strong> <code>extractAccessToken</code> 依次查找 query <code>token</code>、cookie <code>access_token</code> 和 <code>Authorization: Bearer</code>。普通的 REST 请求能自由设置请求头，所以用 Bearer 最省事；<code>&lt;video&gt;</code> / <code>&lt;audio&gt;</code> 这类媒体元素由浏览器自己发起请求，MSE 和 hls.js 也一样加不了自定义头，只能在媒体 URL 上挂一个 <code>?token=</code>；Socket.IO 读不到 URL 之外的信息，直接从 cookie 或 <code>handshake.auth.token</code> 里取。前端的 <code>appendAuthToken()</code> 只对本站 <code>/api/</code> 路径附加 token，专门处理 HTTP 下没有 auth cookie 的场景。</p></li><li><p><strong>密钥自举。</strong> <code>loadOrCreateSecret</code> 按顺序找密钥：先看环境变量，再看 <code>config/jwt-secrets.json</code>（内容长度 ≥32 才采信），都没有就自动生成一个 64 位 hex 密钥写回该文件。首次启动因此不需要任何配置，生产环境建议显式设置环境变量。</p></li><li><p><strong>refresh 不轮换。</strong> <code>/refresh</code> 只重新签发 access token 并重写 cookie，refresh token 本身长期不变。</p></li><li><p><strong>令牌吊销。</strong> <code>User.tokenInvalidBefore</code> 是一个时间戳，早于它的令牌一律失效。<code>authenticateToken</code> 中只要满足 <code>iat*1000 &lt; invalidBefore</code> 就返回 401。改密码、删除用户后会调用 <code>invalidateUserTokens()</code> 写库并刷新内存缓存（缓存 TTL 60s，改密路径主动写缓存，保证立即生效）。游客（userId=0）没有 User 行，跳过这项检查。</p></li></ul><h3 id="cookie-属性与内网穿透兜底" tabindex="-1">Cookie 属性与内网穿透兜底 <a class="header-anchor" href="#cookie-属性与内网穿透兜底" aria-label="Permalink to &quot;Cookie 属性与内网穿透兜底&quot;">​</a></h3><p>Cookie 能不能下发、带什么属性，取决于请求是同站还是跨站，以及走的是 HTTP 还是 HTTPS。几种组合的结果见下表。</p><table tabindex="0"><thead><tr><th>场景</th><th>结果</th></tr></thead><tbody><tr><td>同站 / 任意协议</td><td><code>sameSite: &#39;lax&#39;</code>（HTTPS 时加 <code>secure</code>）</td></tr><tr><td>跨站 + HTTPS</td><td><code>sameSite: &#39;none&#39;, secure: true</code></td></tr><tr><td>跨站 + HTTP</td><td><strong>无解</strong>（SameSite=None 必须 Secure），需同站反代或升级 HTTPS</td></tr><tr><td>HTTP 请求</td><td><strong>不下发 cookie</strong>（<code>isRequestSecure</code> 为 false 直接 return），统一走 Bearer</td></tr></tbody></table><p><code>isRequestSecure</code>（判断当前请求是否走 HTTPS 的函数）依次用三个线索判断，前一个不成立才看下一个：Express 自己解析出的 <code>req.secure</code>；反向代理写入的 <code>X-Forwarded-Proto</code>（反向代理用来告知原始协议的头）第一段是否为 <code>https</code>；以及 <code>Origin</code> 请求头是否以 <code>https://</code> 开头。最后这条是给内网穿透和 HTTP 反代 HTTPS 准备的兜底；伪造 <code>Origin</code> 的影响仅限于对 http 连接下发 Secure cookie，浏览器会直接丢弃，不构成安全恶化。跨站判定按 schemeful same-site 规则（把协议也算进比较的 same-site 判定），并忽略端口，以兼容端口映射。</p><h2 id="注册模式与游客" tabindex="-1">注册模式与游客 <a class="header-anchor" href="#注册模式与游客" aria-label="Permalink to &quot;注册模式与游客&quot;">​</a></h2><p>服务器提供三种注册模式，另外给未登录的人留了一条游客通道。</p><ul><li><p><strong>注册模式</strong>有三种：<code>open</code> 注册即激活；<code>approval</code> 注册后需要审核，这是默认值，注册后状态为 pending；<code>closed</code> 直接关闭注册。</p></li><li><p><strong>用户名与密码规则。</strong> 用户名必须匹配正则 <code>/^[\\u4e00-\\u9fa5A-Za-z0-9_\\- ]{2,24}$/</code>，密码至少 4 位。在 <code>approval</code> 模式下，注册后状态为 pending，此时登录与 refresh 都返回 403「账号正在审核中」；root 审核通过后状态置为 active，如果原角色是 guest 就提升为 user。</p></li><li><p><strong>游客（guest）。</strong> <code>POST /api/auth/guest</code> 不需要鉴权，直接签发 <code>userId=0, role=&#39;guest&#39;</code> 的令牌，<code>/auth/me</code> 返回一个虚拟用户而不查库，所以未登录的人也能加入房间观看。游客的有效期比正式用户短（refresh 7d 对 30d），这样在没有凭证可吊销的场景下能压低滥用面。</p></li><li><p><strong>默认密码检测。</strong> 登录响应会带上 <code>mustChangePassword</code>，由 bcrypt（一种专门做密码哈希的算法）比对 <code>&#39;root&#39;</code> 得出。</p></li><li><p><strong>限流。</strong> 登录为每 IP 15 分钟 20 次；连续失败 5 次锁 15 分钟（该功能默认关闭，设置 <code>ENABLE_LOGIN_LOCK=true</code> 开启）；改密为每用户 1 分钟 3 次。</p></li></ul><h2 id="角色模型" tabindex="-1">角色模型 <a class="header-anchor" href="#角色模型" aria-label="Permalink to &quot;角色模型&quot;">​</a></h2><p>ZViewer 的角色分两层：全局角色决定账号在整个系统里的身份，房间运行时角色决定这个人在某个房间里能做什么。两层叠加后才得出最终权限。</p><h3 id="全局角色" tabindex="-1">全局角色 <a class="header-anchor" href="#全局角色" aria-label="Permalink to &quot;全局角色&quot;">​</a></h3><p>全局角色有四种，权限范围依次收窄，具体能力见下表。</p><table tabindex="0"><thead><tr><th>角色</th><th>权限</th></tr></thead><tbody><tr><td><code>root</code></td><td>全部房间控制/删除、用户审核与角色管理、系统设置、更新、服务器文件</td></tr><tr><td><code>admin</code></td><td>创建并完全控制自己的房间；管理后台只读（不能删除他人房间）</td></tr><tr><td><code>user</code></td><td>加入房间观看、评论弹幕（审核通过后）</td></tr><tr><td><code>guest</code></td><td>同 user（未登录或 pending）</td></tr></tbody></table><p>在 HTTP 侧，管理路由统一挂载 <code>authenticateToken + adminOnly</code>（root 和 admin 都放行），root-only 端点则单独导出 <code>requireRoot</code> 来保护。修改角色只允许在 <code>admin</code> 和 <code>user</code> 之间进行，root 账户不可改。root 的判定同时看两个条件：<code>role===&#39;root&#39;</code> 或 <code>username===&#39;root&#39;</code>。</p><h3 id="房间运行时角色-叠加" tabindex="-1">房间运行时角色（叠加） <a class="header-anchor" href="#房间运行时角色-叠加" aria-label="Permalink to &quot;房间运行时角色（叠加）&quot;">​</a></h3><p>房主不是持久化的全局角色，而是运行时角色：Session 表中持有 <code>role: &#39;sharer&#39; &amp;&amp; endedAt IS NULL</code> 的那个会话就是当前房主。<code>canViewerPerform</code> 按固定顺序叠加判定：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>房主（短路 true） → root（true） → 房管（查矩阵 moderator）</span></span>
<span class="line"><span>→ admin（查矩阵 admin） → user（查矩阵 user） → guest（false）</span></span></code></pre></div><ul><li><p><strong>权限矩阵。</strong> 系统设置里的矩阵覆盖 <code>addMovie / manageMovie / musicQueue / kickViewer / muteViewer</code> 五个动作和 <code>moderator / admin / user</code> 三列。缺省兼容值为房管与 admin 允许、user 拒绝。前端镜像同一份矩阵做 UI 门控（<code>systemSettingsStore.canRoomViewerPerform</code>）。</p></li><li><p><strong>房管（上限 10 名）。</strong> 房管的目标必须是登录用户、非房主本人、且当前在房间内；名单以 JSON 数组持久化在 <code>Room.moderators</code>。房管有防篡权规则 <code>canModeratorActOn</code>：不能操作房主、其他房管和 root。</p></li><li><p><strong>权限校验缓存。</strong> 校验结果带 5 秒 TTL 缓存（容量 1000 条），踢出、转交、会话结束时主动失效。</p></li><li><p><strong>Socket 侧的身份来源。</strong> 角色取自握手时写入的 <code>socket.data.userId / role / username</code>，身份不可伪造；控制申请类事件里的 <code>from</code> 由服务端注入。</p></li><li><p><strong>建房权限。</strong> guest 恒为否；root/admin 恒为是；user 取决于 <code>roomCreationMode === &#39;all-users&#39;</code>，默认为 admin-only。</p></li></ul><h2 id="前端登录态-预热与判定的边界" tabindex="-1">前端登录态：预热与判定的边界 <a class="header-anchor" href="#前端登录态-预热与判定的边界" aria-label="Permalink to &quot;前端登录态：预热与判定的边界&quot;">​</a></h2><p>这一节的约定用来处理「房间链接需要输入两次地址」这类问题。</p><ul><li><p><code>authStore</code> 的持久化 key 是 <strong><code>zcontrol-auth-storage</code></strong>，持久化的字段有 <code>user / isAuthenticated / hasLoggedOut / autoLoginStatus</code>。<strong>token 不持久化</strong>，cookie 才是令牌的存储介质。</p></li><li><p><code>autoLoginStatus</code> 虽然持久化，但<strong>它只代表上一次页面生命周期</strong>。它唯一的用途是让 <code>useSocket</code> 判断能不能提前建连，避免以匿名状态建连被拒。</p></li><li><p><code>authResolved</code> <strong>不持久化</strong>，它代表本次页面加载的鉴权引导终态。<code>RequireAuth</code> 只看这一个值：没有 resolved 时原地渲染 <code>null</code> 等待，不做重定向；已经 resolved 且未认证才跳转 <code>/login</code>。别用持久化下来的 <code>done</code> 判断要不要跳转登录页，那是上一次页面生命周期留下的残留值。登出后虽然会清掉用户信息，但这个字段可能还停在 <code>done</code>，结果第一次访问的人还没经过鉴权就被直接弹去登录页。</p></li><li><p>登出和会话失效统一走 <code>expireSession()</code>：清掉 user，并把 <code>autoLoginStatus</code> 重置回 <code>idle</code>，不可置为 <code>done</code>。</p></li><li><p><strong>启动流程（AuthInitializer）。</strong> 先 <code>GET /auth/me</code>，网络错误最多重试 8 次，间隔 2s；确认失效就调用 <code>expireSession()</code>；然后自动领游客令牌，最多 3 次，退避采用 1.5s×n，只在 429、5xx 和网络错误时重试；最后 <code>reconnectSocket()</code>。无论结果如何，终态都必须置为 resolved。</p></li></ul><h2 id="连接降级与-401-拦截" tabindex="-1">连接降级与 401 拦截 <a class="header-anchor" href="#连接降级与-401-拦截" aria-label="Permalink to &quot;连接降级与 401 拦截&quot;">​</a></h2><p>断网、令牌过期、服务器重启都会让连接或请求失败，这一节说明系统如何逐级退让，以及如何避免刷屏式的重复重试。</p><ul><li><p><strong>Socket 三级降级</strong>，由 <code>connect_error</code> 触发：第一步，错误消息命中鉴权类关键词时调用 <code>POST /auth/refresh</code>，成功后重连，并发安全；第二步，refresh 失败则调用 <code>POST /auth/guest</code>，降级为游客身份；第三步，游客也失败才 <code>logout()</code>。网络异常不会导致登出，交给 socket.io 自动重试。</p></li><li><p><strong>HTTP 401/403 拦截</strong>，由 <code>apiFetch</code> 处理：收到状态码后自动调用 <code>refreshAccessToken()</code>，再带上 <code>_retried</code> 标记重试一次。并发刷新复用同一个 in-flight Promise；refresh 明确失败后置 <code>sessionExpired</code> 阻止级联重试，登录或领取游客身份成功后重置该标记。</p></li><li><p>媒体请求不走 <code>apiFetch</code>，播放引擎在 401/403 时单独触发刷新重试，见<a href="/advanced/video-pipeline">视频管线</a>。</p></li></ul><h2 id="接口权限查看" tabindex="-1">接口权限查看 <a class="header-anchor" href="#接口权限查看" aria-label="Permalink to &quot;接口权限查看&quot;">​</a></h2><p>按权限等级可以把接口大致分成几组，先看整体轮廓。</p><ul><li><p>公开：健康检查、注册模式与公开设置、注册与登录、游客令牌，以及 B站图片代理；其余代理需要登录，防止带宽滥用。</p></li><li><p>登录即可：挂载点、解析、代理、音乐、房间加入。</p></li><li><p>房主/root：房间删除、改名等房间级写操作。</p></li><li><p>admin/root：管理后台读取；root-only 则包含用户审核、角色修改、删除用户、系统设置修改、更新、服务器文件。</p></li><li><p>逐条标注见 <a href="/advanced/api">REST API 参考</a>。</p></li></ul>`,32)])])}const g=o(c,[["render",a]]);export{u as __pageData,g as default};
